// Arma el cuerpo para Evolution. Si la consulta no devolvió fila, no sigue.
const TEXTO = "Hola, te recordamos con mucho cariño que contamos con tu presencia en la celebración de los 60 años de Edvin.\n\n📅 Sábado 26 de diciembre de 2026\n🕟 4:30 p. m.\n📍 Turicentro El Paraíso, 9a Calle, Zona 5, Villa Nueva\n\nSi aún no has confirmado, puedes hacerlo aquí usando este mismo número de teléfono:\nhttps://rodolfo60s.isdomana.com\n\n¡Te esperamos con mucho cariño para celebrar juntos esta gran bendición! ❤️🎊";
const salida = [];
$input.all().forEach((item, i) => {
  const tel = item.json.telefono;
  if (typeof tel === 'string' && /^\+[1-9][0-9]{7,14}$/.test(tel)) {
    salida.push({
      json: { telefono: tel, number: tel.slice(1), text: TEXTO, delay: 3000 },
      pairedItem: { item: i },
    });
  }
});
return salida;

