UPDATE invites.envios
SET estado = 'enviado', wa_message_id = nullif($2, ''), error = NULL, actualizado_en = now()
WHERE telefono = $1 AND estado = 'enviando';

UPDATE invites.envios
SET estado = 'fallido', error = left($2, 1000), actualizado_en = now()
WHERE telefono = $1 AND estado = 'enviando';
